"""L10M closed-loop target policy with safety gating, lock hysteresis, and
heading-aware approach control.
"""


# EVOLVE-BLOCK-START
def decide(observation, memory):
    """Select a safe target-directed action using bounded finite-state memory.

    The controller first enforces safety, then preserves a confirmed lock,
    briefly verifies newly acquired tracks, reacquires conservatively after
    loss, and uses bearing/heading plus corridor availability to minimize
    unnecessary steering.
    """
    memory = dict(memory or {})
    state = memory.get("state", "IDLE")
    scan_direction = memory.get("scan_direction", "SCAN_LEFT")
    scan_count = int(memory.get("scan_count", 0))
    last_action = memory.get("last_action", "")

    visible = bool(observation["target_visible"])
    bearing = float(observation["target_bearing"])
    distance = observation["target_distance_class"]
    target_confidence = float(observation["target_confidence"])
    identity_confidence = float(observation["target_identity_confidence"])
    track_age = int(observation["track_age"])
    lost_steps = int(observation["lost_steps"])
    safety_confidence = float(observation["safety_confidence"])
    closing_risk = float(observation["closing_risk"])
    heading_error = float(observation["heading_error"])

    def emit(action, confidence, next_state):
        memory["state"] = next_state
        memory["last_action"] = action
        return action, confidence, memory

    # Safety is an unconditional hard gate.
    if safety_confidence < 0.60 or closing_risk >= 0.75:
        return emit("STOP", 0.99, "STOPPED")

    confirmed = (
        visible
        and target_confidence >= 0.55
        and identity_confidence >= 0.60
    )

    # Loss handling: hold once to avoid acting on stale geometry, then scan
    # with a stable direction and only reverse after a bounded scan interval.
    if not confirmed:
        if state in {"LOCKED", "APPROACH", "VERIFY", "REACQUIRE"} or lost_steps > 0:
            if lost_steps <= 1:
                return emit("STOP", 0.92, "REACQUIRE")
            scan_count += 1
            if scan_count >= 3:
                scan_direction = (
                    "SCAN_RIGHT" if scan_direction == "SCAN_LEFT"
                    else "SCAN_LEFT"
                )
                scan_count = 0
            memory["scan_direction"] = scan_direction
            memory["scan_count"] = scan_count
            return emit(scan_direction, 0.74, "REACQUIRE")
        memory["scan_count"] = 0
        return emit(scan_direction, 0.72, "SEARCH")

    memory["scan_count"] = 0
    memory["scan_direction"] = scan_direction

    # Require a short, stable track unless confidence is exceptionally strong.
    if track_age < 2 and not (
        track_age >= 1
        and target_confidence >= 0.82
        and identity_confidence >= 0.85
    ):
        return emit("SLOW_DOWN", 0.80, "VERIFY")

    # Near targets are considered arrived only when alignment is confirmed.
    if distance == "near":
        if abs(heading_error) <= 15.0 and identity_confidence >= 0.80:
            return emit("ARRIVED", 0.96, "ARRIVED")
        correction = heading_error if abs(heading_error) > 5.0 else bearing
        if correction < -5.0 and observation["corridor_left"]:
            return emit("VEER_LEFT", 0.86, "APPROACH")
        if correction > 5.0 and observation["corridor_right"]:
            return emit("VEER_RIGHT", 0.86, "APPROACH")
        if observation["corridor_center"] and abs(correction) <= 10.0:
            return emit("FORWARD", 0.84, "APPROACH")
        if observation["corridor_left"]:
            return emit("VEER_LEFT", 0.78, "APPROACH")
        if observation["corridor_right"]:
            return emit("VEER_RIGHT", 0.78, "APPROACH")
        return emit("STOP", 0.98, "STOPPED")

    # Far/medium approach: steer only for meaningful bearing error; otherwise
    # continue through the center corridor to improve path efficiency.
    if bearing < -12.0 and observation["corridor_left"]:
        return emit("VEER_LEFT", 0.89, "APPROACH")
    if bearing > 12.0 and observation["corridor_right"]:
        return emit("VEER_RIGHT", 0.89, "APPROACH")
    if observation["corridor_center"] and abs(bearing) <= 12.0:
        return emit("FORWARD", 0.91, "APPROACH")
    if observation["corridor_left"]:
        return emit("VEER_LEFT", 0.81, "APPROACH")
    if observation["corridor_right"]:
        return emit("VEER_RIGHT", 0.81, "APPROACH")
    return emit("STOP", 0.98, "STOPPED")
# EVOLVE-BLOCK-END
